class Spacecraft {
  constructor(name, fuel) {
    this.name = name;
    this.fuel = fuel;
  }

  launch() {
    if (this.fuel >= 10) {
      this.fuel -= 10;
      return `${this.name} launched! Fuel: ${this.fuel}`;
    }
    return `${this.name} failed to launch! Insufficient fuel.`;
  }
}

